var e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Tự động hóa máy in của bạn bằng các quy tắc NẾU-THÌ an toàn. Mặc định tắt; tự bạn kích hoạt từng quy tắc.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Chưa có quy tắc nào. Thêm một quy tắc bên dưới, rồi kích hoạt khi bạn sẵn sàng.`}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:`Bộ máy quy tắc đang BẬT`}},off:{t:0,b:{t:2,i:[{t:3}],s:`Bộ máy quy tắc đang TẮT`}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:`Bật`}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:`Tắt`}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:`Không có gì chạy cho đến khi cả bộ máy lẫn quy tắc riêng lẻ đều được bật.`}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:`Khi một bản in hoàn tất`}},print_error:{t:0,b:{t:2,i:[{t:3}],s:`Khi máy in gặp lỗi`}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:`Khi một bộ gia nhiệt vượt quá`}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:`Khi một bộ gia nhiệt giảm dưới`}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:`Ghi một thông báo`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`Chạy một lệnh g-code`}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:`Đã kích hoạt`}},arm:{t:0,b:{t:2,i:[{t:3}],s:`Chưa kích hoạt`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`Sửa`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Xóa`}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:`Xóa quy tắc`}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:`Tên quy tắc`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`vd. Tắt bộ gia nhiệt sau khi in`}},trigger:{t:0,b:{t:2,i:[{t:3}],s:`Nếu (kích hoạt)`}},action:{t:0,b:{t:2,i:[{t:3}],s:`Thì (hành động)`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`Bộ gia nhiệt`}},value:{t:0,b:{t:2,i:[{t:3}],s:`Nhiệt độ (°C)`}},message:{t:0,b:{t:2,i:[{t:3}],s:`Thông điệp`}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Hiển thị trong nhật ký quy tắc`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`vd. TURN_OFF_HEATERS`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Lưu quy tắc`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Hủy`}},add:{t:0,b:{t:2,i:[{t:3}],s:`Thêm một quy tắc`}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:`Hoạt động gần đây`}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:`đã thông báo`}},ran:{t:0,b:{t:2,i:[{t:3}],s:`đã chạy g-code`}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:`đã bỏ qua (máy in đang bận)`}},error:{t:0,b:{t:2,i:[{t:3}],s:`lỗi`}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Hướng dẫn`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Hướng dẫn bộ máy quy tắc`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Đóng`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Bộ máy quy tắc là gì?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Nó theo dõi máy in và chạy một hành động khi điều kiện bạn đặt được thỏa mãn - ví dụ, ghi một ghi chú khi một bản in hoàn tất, hoặc tắt các bộ gia nhiệt. Mỗi quy tắc là NẾU (một kích hoạt) THÌ (một hành động).`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Cách nó giữ an toàn`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Bộ máy mặc định tắt và mỗi quy tắc phải được kích hoạt riêng lẻ, nên không có gì chạy bất ngờ. Một quy tắc kích hoạt một lần khi điều kiện của nó lần đầu trở thành đúng. Các hành động g-code chỉ chạy khi máy in rảnh - chúng bị từ chối trong lúc đang in - và mọi kết quả đều được ghi lại.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Thuật ngữ`}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:`Kích hoạt`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Điều kiện khởi động một quy tắc, vd. một bản in hoàn tất hoặc một bộ gia nhiệt vượt qua một mức nhiệt độ.`}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:`Hành động`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Việc quy tắc thực hiện khi nó kích hoạt: ghi một thông báo, hoặc chạy một lệnh g-code (chỉ khi rảnh).`}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:`Đã kích hoạt`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Một quy tắc đang được bật. Các quy tắc chưa kích hoạt vẫn được giữ nhưng không bao giờ chạy.`}}}}}}};export{e as default};